1	//! Rust port of `url-parser/tests/test15.cpp`.
2	//!
3	//! Takes six positional arguments — scheme, host, port, path, query, fragment —
4	//! builds a `URL` from them with `URL::from_components`, and prints the six
5	//! components followed by `to_string()` and `is_valid()`, one per line.
6	//!
7	//! Build either way; both produce the same binary:
8	//!   rustc -O test15.rs      # -> ./test15
9	//!   cargo build --release   # -> ./target/release/test15
10	
11	#[path = "url_parser/mod.rs"]
12	mod url_parser;
13	
14	use url_parser::cstdlib::stoi_or_terminate;
15	use url_parser::URL;
16	
17	fn main() {
18	    let argv: Vec<String> = std::env::args().collect();
19	    if argv.len() < 7 {
20	        std::process::exit(1);
21	    }
22	
23	    let scheme = &argv[1];
24	    let host = &argv[2];
25	    // `test15.cpp` calls `std::stoi` with no `try` block, so a port argument
26	    // that is not a number aborts the process instead of reporting an error.
27	    let port = stoi_or_terminate(&argv[3]);
28	    let path = &argv[4];
29	    let query = &argv[5];
30	    let fragment = &argv[6];
31	
32	    let parser = URL::from_components(scheme, host, port, path, query, fragment);
33	
34	    println!("{}", parser.scheme());
35	    println!("{}", parser.host());
36	    println!("{}", parser.port());
37	    println!("{}", parser.path());
38	    println!("{}", parser.query());
39	    println!("{}", parser.fragment());
40	    println!("{}", parser);
41	    // `std::cout << bool` prints 1 or 0, not "true"/"false".
42	    println!("{}", i32::from(parser.is_valid()));
43	}
